import {icon} from './icons.mjs';
import * as pdfjs from './vendor/pdf.mjs';
import {correctInvoiceFields,VENDORS,DEFAULT_POS,POLICY_VERSION,emptyState,extractInvoice,evaluate,remainingFor,money,cents,parsePoCsv} from './engine.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
const KEY='ledgerline.unslop.workspace.v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageError='';
function read(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s===null)return emptyState();if(s.version!==1||!Array.isArray(s.runs)||!Array.isArray(s.pos))throw new Error('unsupported workspace data');return s;}catch(e){storageError='Saved workspace could not be read. Export or clear this site’s storage before proceeding; existing data has not been overwritten.';return emptyState();}}
let state=read(),view='overview',running=false,activeRun=null,lastFocus=null,dbPromise,previewDoc=null,previewPage=1;
const samples=[
 {file:'01-happy-path.pdf',title:'Clean invoice',subtitle:'Northstar Studio · NS-2048 · $1,200.00',outcome:'Approved',tag:'Baseline'},
 {file:'01-happy-path.pdf',title:'Duplicate invoice',subtitle:'Run the clean invoice first',outcome:'Blocked',tag:'Case 01'},
 {file:'02-split-overrun.pdf',title:'Split PO overrun',subtitle:'Harbor Cloud · $4,500.00 requested',outcome:'Needs review',tag:'Case 02'},
 {file:'03-ambiguous-po.pdf',title:'Missing PO reference',subtitle:'Cedar Office Supply · two eligible orders',outcome:'Needs review',tag:'Case 03'},
 {file:'04-scanned.pdf',title:'Image-only invoice',subtitle:'Northstar Studio · verify against the scan',outcome:'Needs review',tag:'Case 04'}
];
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
async function lock(fn){if(!navigator.locks)throw new Error('This browser lacks safe workspace locking. Use a current Chrome, Edge, Firefox or Safari browser.');return navigator.locks.request('ledgerline-unslop-workspace',fn);}
function save(s){if(storageError)throw new Error(storageError);s.revision=(s.revision||0)+1;localStorage.setItem(KEY,JSON.stringify(s));state=s;}
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('ledgerline-unslop-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(new Error('Cannot access local file storage. Enable site storage and retry.'));});return dbPromise;}
async function filePut(id,file){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(new Error('File storage failed. Free browser storage and retry.'));});}
async function fileGet(id){const d=await db();return new Promise((resolve,reject)=>{const req=d.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=reject;});}
function statusClass(s){return s==='Needs review'?'review':s==='Blocked'||s==='Suspended'?'blocked':s==='Approved'||s==='Active'?'approved':'';}
function badge(s){return `<span class="status ${statusClass(s)}">${esc(s)}</span>`;}
const when=iso=>new Date(iso).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});
const seconds=ms=>`${(ms/1000).toFixed(1)} s`;
const plural=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const initials=name=>String(name||'').trim().split(/\s+/).map(w=>w[0]||'').join('').slice(0,2).toUpperCase();
// Auditor's tickmark: the reviewer's blue-ink mark beside a figure a control has traced, footed or agreed.
const tickmark=()=>`<svg class="tickmark" viewBox="0 0 16 16" aria-hidden="true"><path d="M2.6 8.6c1.3.8 2.3 1.9 3.2 3.4C7.7 8.3 10.2 5.3 13.6 3"/></svg>`;
function newButton(){return `<button class="btn primary" data-action="new">${icon('Plus')} Process invoice</button>`;}
function heading(title,sub,actions=newButton()){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metrics(){const approved=state.runs.filter(r=>r.status==='Approved'),review=state.runs.filter(r=>r.status==='Needs review'),blocked=state.runs.filter(r=>r.status==='Blocked'),reserved=approved.reduce((sum,r)=>sum+(r.fields.currency==='USD'?r.fields.total:0),0);return `<div class="metrics">${[
 ['Processed',state.runs.length,'Saved in this browser'],['Ready for AP',approved.length,approved.length?`${money(reserved)} reserved`:'Nothing reserved yet'],['Needs review',review.length,'Waiting for verified evidence'],['Blocked',blocked.length,'No budget reserved']
 ].map(([label,value,note],i)=>`<article class="metric ${i===2&&value?'attention':''}"><div class="metric-top">${label}</div><div class="metric-number">${value}</div><div class="metric-bottom">${note}</div></article>`).join('')}</div>`;}
function scenarioList(){return `<div class="sample-heading"><span>Sample invoices</span><span>1 baseline · 4 exceptions</span></div><div class="scenario-columns"><span>Input</span><span>Expected decision</span></div><div class="scenario-list">${samples.map((v,i)=>`<button class="scenario" data-sample="${i}"><span class="scenario-index">${String(i+1).padStart(2,'0')}</span><span class="scenario-content"><span class="scenario-title">${v.title}</span><span class="scenario-sub">${v.subtitle}</span></span><span class="scenario-outcome status ${v.outcome==='Approved'?'approved':v.outcome==='Blocked'?'blocked':'review'}">${v.outcome}</span><span class="scenario-arrow">${icon('ArrowUpRight')}</span></button>`).join('')}</div>`;}
function intake(){return `<div class="intake" id="drop-zone"><span class="intake-sheet" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i>${tickmark()}</span><div class="intake-copy"><h3>Drop an invoice PDF</h3><p>Extract the evidence, check the PO and get a decision</p><div class="upload-actions"><button class="btn" data-action="upload">${icon('Upload')} Choose invoice PDF</button><span class="intake-note">10 MB max · 20 pages</span></div></div></div>`;}
function overview(){return heading('Invoice decisions',`Each invoice PDF is checked against its purchase order and policy ${POLICY_VERSION}`)+metrics()+`<div class="overview-grid"><section class="panel"><div class="panel-header"><div><h2>Invoice intake</h2><p>Upload a PDF or run a prepared case</p></div></div>${intake()}${scenarioList()}</section><section class="panel workflow-panel"><div class="panel-header"><div><h2>From file to decision</h2><p>Each stage is shown while it runs</p></div></div><div class="flow">${[
 ['Receive','Fingerprint the original PDF'],['Extract','Keep each field linked to its source'],['Validate','Check supplier, date and arithmetic'],['Match','Reconcile the PO and available budget'],['Decide','Approve, request evidence, or block']
 ].map(([t,sub],i)=>`<div class="flow-row"><span class="flow-num">${String(i+1).padStart(2,'0')}</span><div><div class="flow-title">${t}</div><div class="flow-sub">${sub}</div></div></div>`).join('')}</div><div class="flow-footer">${icon('ShieldCheck')}<span>Approval means ready for AP posting, and no payment is made here</span></div></section></div><section class="panel run-table-panel"><div class="panel-header"><div><h2>Recent decisions</h2><p>The latest five runs and their next step</p></div><button class="btn small" data-go="history">View history ${icon('ArrowRight')}</button></div>${runTable(state.runs.slice().reverse().slice(0,5))}</section>`;}
function runTable(runs){if(!runs.length)return `<div class="empty-state"><span class="empty-rule"></span><div><strong>No invoices processed yet</strong><p>Upload a PDF or choose a sample case to start the decision trail</p></div></div>`;return `<div class="table-wrap"><table><thead><tr><th>Invoice / supplier</th><th class="num">Amount</th><th>Purchase order</th><th>Status</th><th>Run reference</th></tr></thead><tbody>${runs.map(r=>`<tr tabindex="0" role="button" aria-label="Open ${esc(r.fields.invoiceNumber||r.filename)}" data-run="${esc(r.id)}"><td><div class="td-primary">${esc(r.fields.invoiceNumber||'Unreadable invoice')}</div><div class="td-secondary">${esc(r.fields.vendor||r.filename)}</div></td><td class="num">${r.fields.total!==null?esc(money(r.fields.total,r.fields.currency||'USD')):'—'}</td><td class="reference">${esc(r.matchedPo||'Unmatched')}</td><td>${badge(r.status)}</td><td><div class="reference">${esc(r.id)}</div><div class="td-secondary">${when(r.createdAt)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function history(){return heading('Invoice history','Search runs, resolve exceptions and export the decision trail',`<button class="btn" data-action="export-all">${icon('Download')} Export JSON</button> ${newButton()}`)+metrics()+`<section class="panel"><div class="toolbar"><input id="search" type="search" placeholder="Search" aria-label="Search invoice history"><select id="status-filter" aria-label="Filter by status"><option value="all">All statuses</option><option>Approved</option><option>Needs review</option><option>Blocked</option></select><span class="muted" id="history-count">${plural(state.runs.length,'run')}</span></div><div id="history-table">${runTable(state.runs.slice().reverse())}</div></section>`;}
function orders(){return heading('Purchase orders','Available budget is the PO total less opening commitments and approved invoices',`<button class="btn" data-action="export-pos">${icon('Download')} Export CSV</button> <button class="btn ${state.runs.length?'':'primary'}" data-action="import-pos" ${state.runs.length?'disabled title="Reset the workspace before changing its PO register"':''}>${icon('Upload')} Import CSV</button>`)+`<div class="notice">All PO amounts include tax. Opening commitments represent earlier invoices outside this demo. Approved runs reserve additional budget; reviewed or blocked invoices reserve none. CSV amounts are in dollars, not cents.</div><section class="panel"><div class="panel-header"><h2>PO register</h2><span class="panel-tag">${plural(state.pos.length,'order')}</span></div><div class="table-wrap"><table><thead><tr><th>PO / description</th><th>Supplier</th><th class="num">Authorized</th><th class="num">Opening commitment</th><th class="num">Remaining</th><th>Status</th></tr></thead><tbody>${state.pos.map(p=>{const remaining=remainingFor(p,state),share=n=>Math.max(0,Math.min(100,n/p.total*100)),approvedSpend=Math.max(0,p.total-p.committed-remaining);return `<tr><td><div class="td-primary">${esc(p.id)}</div><div class="td-secondary">${esc(p.description)}</div></td><td>${esc(VENDORS.find(v=>v.id===p.vendorId)?.name||p.vendorId)}</td><td class="num">${money(p.total,p.currency)}</td><td class="num">${money(p.committed,p.currency)}</td><td class="num">${money(remaining,p.currency)}<div class="po-budget" aria-hidden="true"><span class="po-opening" style="width:${share(p.committed)}%"></span><span class="po-approved" style="width:${share(approvedSpend)}%"></span></div></td><td>${esc(p.status.charAt(0).toUpperCase()+p.status.slice(1))}</td></tr>`;}).join('')}</tbody></table></div><div class="po-legend"><span><i class="po-opening"></i>Opening commitment</span><span><i class="po-approved"></i>Approved in this workspace</span></div></section><section class="panel run-table-panel"><div class="panel-header"><h2>Supplier register</h2><span class="muted">Curated aliases · no fuzzy auto-approvals</span></div><div class="supplier-grid">${VENDORS.map(v=>`<div class="supplier"><strong>${esc(v.name)}</strong><small class="reference">${v.id}</small>${badge(v.status==='active'?'Active':'Suspended')}</div>`).join('')}</div></section>`;}
function policy(){return heading('Rules and guide','The input contract, decision controls and the prepared demonstration',`<a class="btn" href="samples/README.txt" download>${icon('Download')} Input guide</a>`)+`<section class="panel"><div class="panel-header"><h2>Scope & operating policy</h2><span class="panel-tag">${POLICY_VERSION}</span></div><div class="policy-content"><div class="policy-grid"><article class="policy-card"><h3>What gets approved</h3><p>Readable, labeled invoice data; an active registered supplier; a valid non-future ISO date; consistent totals; an explicit open PO for that supplier and currency; no duplicate; cumulative spend within budget.</p><h3>A small, bounded tolerance</h3><p>Allow up to the lesser of 2% of the authorized PO total or $25 (25 units in the PO currency). The allowance applies once to cumulative spend, including the opening commitment and all approved runs.</p></article><article class="policy-card"><h3>When a person takes over</h3><p>Missing or conflicting fields, an unreadable scan, ambiguous or absent PO, arithmetic discrepancies, or insufficient PO budget produce “Needs review.” A reviewer can verify fields and add a named audit note; all controls run again.</p><h3>Hard stops</h3><p>Previously approved duplicates, a suspended supplier, or a supplier/PO identity mismatch are blocked. The UI offers no approval override. No payment or external message is sent.</p></article></div><h3>Reading the marks</h3><div class="mark-legend"><div>${tickmark()}<span>A control traced this figure to its PDF line, footed it or agreed it to the PO</span></div><div><span class="initials">DR</span><span>A named reviewer verified the value against the original</span></div></div><h3>Input contract</h3><p>PDFs up to 10 MB and 20 pages. Labels accepted include Vendor / Supplier / From; Invoice number / Invoice no / Invoice #; Date / Invoice date; PO / Purchase order; Currency; Subtotal / Net amount; Tax / VAT / GST; Total / Amount due. Dates must be YYYY-MM-DD. Amounts use decimal points and optional comma thousands separators. Currency must be explicit.</p><p>Optional structured item rows: <code>Item: Design | Qty: 10 | Unit: 100.00 | Amount: 1000.00</code>. Unstructured or bundled items receive total-level checks only. Missing tax is never assumed to be zero. Image-only scans go to manual review; OCR and model-based layout interpretation are future extensions.</p><h3>Demo sequence</h3><ol class="check-list"><li>Start with a fresh workspace. Process the clean Northstar invoice: Approved; PO-1001 remaining falls from $5,000 to $3,800.</li><li>Process the same file again: Blocked; the PO balance stays $3,800.</li><li>Process the Harbor split invoice: Needs review; $4,500 exceeds the $4,000 remaining plus $25 tolerance.</li><li>Process the Cedar invoice: Needs review; two eligible POs, neither selected automatically. Inspect the PDF, verify PO-1003 with procurement, and add your reviewer note before rechecking.</li><li>Process the scan: Needs review. Open the original PDF; enter verified Northstar fields (NS-2049, 2026-10-20, PO-1001, USD, 500, 0, 500) and a reviewer note. Recheck: Approved with original extraction and correction history retained.</li></ol><h3>Architecture & honest limits</h3><p>Real PDF.js extraction + deterministic JavaScript controls. No model API, API key, paid service or server is required. Browser storage contains original PDFs, extracted evidence, PO data and run history. The processing stages reflect actual operations. Runs use a browser lock to prevent competing tabs from committing against stale balances.</p><p>This is a single-browser decision prototype, not an ERP. There is no shared ledger across devices, authenticated reviewer identity, tamper-resistant audit store, OCR, payment integration, goods-receipt matching, foreign exchange or credit-note support. Approval means “ready for AP,” not paid. For production: shared database transactions, role-based approvals, OCR with confidence thresholds, and ERP posting with idempotency.</p><p>There are no invented results or seeded invoice runs. Every row in the dashboard comes from a file you actually processed. Up to 200 runs are retained; export and reset to start another session.</p><div class="notice">This working case study was prepared with AI assistance. All vendors, invoices and purchase orders are fictional. Reviewers are responsible for verified corrections.</div><div class="design-credit">Design guidance: <a href="https://github.com/heydamir/unslop" target="_blank" rel="noopener noreferrer">Unslop by Damir Sokolovsky</a> · CC BY 4.0</div><button class="btn" data-action="reset">Reset demo workspace</button><span class="muted"> Exports should be saved before resetting.</span></div></section>`;}
function render(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});const names={overview:'Overview',history:'Invoice history',orders:'Purchase orders',policy:'Rules & guide'};$('#breadcrumb').textContent=names[view];$('#nav-count').textContent=state.runs.length;document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===view));$('#main').innerHTML=(storageError?`<div class="error-panel">${esc(storageError)}</div>`:'')+({overview,history,orders,policy}[view]());if(view==='overview'){const z=$('#drop-zone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drop-active');});z.addEventListener('dragleave',()=>z.classList.remove('drop-active'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('drop-active');const files=e.dataTransfer.files;if(files.length!==1)return toast('Choose one PDF per run');runFile(files[0]);});}if(view==='history'){$('#search').addEventListener('input',filterHistory);$('#status-filter').addEventListener('change',filterHistory);}}
function filterHistory(){const query=$('#search').value.toLowerCase(),status=$('#status-filter').value;const rows=state.runs.filter(r=>(status==='all'||r.status===status)&&[r.id,r.filename,r.fields.vendor,r.fields.invoiceNumber,r.matchedPo].join(' ').toLowerCase().includes(query)).reverse();$('#history-table').innerHTML=runTable(rows);$('#history-count').textContent=plural(rows.length,'run');}
function nav(open){document.body.classList.toggle('nav-open',open);$('.menu-button')?.setAttribute('aria-expanded',String(open));}
function go(v){view=v;nav(false);render();window.scrollTo({top:0,behavior:'instant'});}
function drawer(title,sub,body,wide=false){if(previewDoc){previewDoc.destroy();previewDoc=null;}lastFocus=document.activeElement;$('#drawer-root').innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-label="${esc(title)}" class="drawer${wide?' wide':''}"><header class="drawer-header"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="close" data-action="close" aria-label="Close dialog">${icon('X')}</button></header><div class="drawer-body">${body}</div></section></div>`;$('.close')?.focus();}
function closeDrawer(){if(running)return toast('Processing is in progress. The decision will appear shortly.');if(previewDoc){previewDoc.destroy();previewDoc=null;}$('#drawer-root').innerHTML='';activeRun=null;lastFocus?.focus();}
function openNew(){if(running)return;drawer('Process an invoice','Choose a PDF or run a prepared case',intake()+scenarioList());const z=$('#drawer-root #drop-zone');z?.addEventListener('dragover',e=>e.preventDefault());z?.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length===1)runFile(e.dataTransfer.files[0]);else toast('Choose one PDF per run');});}
function chooseFile(){if(running)return;const i=document.createElement('input');i.type='file';i.accept='application/pdf,.pdf';i.onchange=()=>{if(i.files[0])runFile(i.files[0]);};i.click();}
async function sample(i){if(running)return;try{const s=samples[i],response=await fetch(`samples/${s.file}`);if(!response.ok)throw new Error('Sample PDF could not be loaded.');const blob=await response.blob();await runFile(new File([blob],s.file,{type:'application/pdf'}));}catch(e){toast(e.message);}}
const tick=()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
function stages(current){return `<div class="stages" aria-label="Processing stages">${['Receive','Extract','Validate','Match PO','Decide'].map((s,i)=>`<div class="stage ${i<current?'done':i===current?'running':''}"><div class="stage-line"></div><span class="stage-index">${i<current?icon('Check'):String(i+1).padStart(2,'0')}</span><span>${s}</span></div>`).join('')}</div>`;}
async function textFromPdf(bytes){const task=pdfjs.getDocument({data:new Uint8Array(bytes),isEvalSupported:false,useSystemFonts:true});let doc;try{doc=await task.promise;if(doc.numPages>20)throw new Error('This PDF has more than 20 pages. Split it into individual invoices.');const rows=[];for(let p=1;p<=doc.numPages;p++){const page=await doc.getPage(p),content=await page.getTextContent();const groups=[];for(const item of content.items){if(!('str'in item)||!item.str.trim())continue;const y=Math.round(item.transform[5]*2)/2;let g=groups.find(g=>Math.abs(g.y-y)<2.5);if(!g){g={y,items:[]};groups.push(g);}g.items.push(item);}rows.push(`--- Page ${p} ---`,...groups.sort((a,b)=>b.y-a.y).map(g=>g.items.sort((a,b)=>a.transform[4]-b.transform[4]).map(i=>i.str).join(' ').trim()));if(rows.join('\n').length>200000)throw new Error('PDF text exceeds the 200,000 character limit. Split the document.');page.cleanup();}return {text:rows.join('\n'),pages:doc.numPages};}finally{if(doc)await doc.destroy();else await task.destroy();}}
async function runFile(file){
 if(running)return;
 if(storageError)return toast(storageError);
 if(file.size>10*1024*1024||file.size===0)return toast('Choose a non-empty PDF no larger than 10 MB.');
 running=true;activeRun=null;
 const start=performance.now(),logs=[];let step=0;
 drawer('Processing invoice',file.name,`<div id="live-body" aria-live="polite"></div>`);
 const update=async(s,detail)=>{step=s;logs.push({at:new Date().toISOString(),stage:s,detail});$('#live-body').innerHTML=`<div class="file-strip">${icon('FileText')}<div><strong>${esc(file.name)}</strong><small>${(file.size/1024).toFixed(1)} KB · Processing locally</small></div><span class="status running">Running</span></div>${stages(s)}<div class="live-log">${logs.map(l=>`<div><span>${String(l.stage+1).padStart(2,'0')}</span>${esc(l.detail)}</div>`).join('')}</div><p class="progress-note">Reading the actual file and evaluating its evidence. This view updates as each stage completes.</p>`;await tick();await new Promise(resolve=>setTimeout(resolve,350));};
 try{
  await update(0,'Receiving the PDF and computing its SHA-256 fingerprint.');
  const bytes=await file.arrayBuffer();const header=new TextDecoder().decode(bytes.slice(0,1024));if(!header.includes('%PDF-'))throw new Error('This file does not contain a valid PDF header.');
  const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
  await update(1,'Extracting text from every PDF page.');
  const extracted=await textFromPdf(bytes),fields=extractInvoice(extracted.text);
  const meaningful=extracted.text.replace(/--- Page \d+ ---/g,'').trim();if(meaningful.length<30)fields.warnings.push('No usable searchable text. OCR is not configured. Verify fields against the original image.');
  await update(2,`Checking ${Object.keys(fields.sources).length} labeled fields, supplier identity and invoice arithmetic.`);
  const provisional=evaluate(fields,read(),{hash});
  await update(3,provisional.matchedPo?`Matched ${provisional.matchedPo}; checking currency and cumulative PO spend.`:`PO match needs review; ${provisional.candidates.length} candidate(s).`);
  await update(4,'Rechecking the latest ledger under a workspace lock and saving the decision.');
  const result=await lock(async()=>{const s=read();if(s.runs.length>=200)throw new Error('Workspace contains 200 runs. Export the audit trail, then reset to continue.');const decision=evaluate(fields,s,{hash});const id=`RUN-${String(s.runs.length+1).padStart(4,'0')}`;const r={id,createdAt:new Date().toISOString(),filename:file.name,filesize:file.size,hash,pages:extracted.pages,rawText:extracted.text,fields,originalFields:structuredClone(fields),corrections:[],logs,...decision,durationMs:Math.round(performance.now()-start),registerSnapshot:structuredClone(s.pos),priorApproved:s.runs.filter(r=>r.status==='Approved').map(r=>({id:r.id,matchedPo:r.matchedPo,total:r.fields.total,currency:r.fields.currency})),source:'PDF upload'};await filePut(id,file);s.runs.push(r);save(s);return r;});
  running=false;render();showRun(result.id);toast(`${result.status} · decision saved to invoice history`);
 }catch(e){running=false;$('#live-body').innerHTML=`${stages(step)}<div class="error-panel"><strong>The file could not be processed.</strong><br>${esc(e.name==='PasswordException'?'Password-protected PDF. Upload an unlocked copy.':e.message)}<br>No invoice approval or budget commitment was saved.</div><div class="result-actions"><button class="btn primary" data-action="upload">Choose another PDF</button><button class="btn" data-action="close">Close</button></div>`;}
}
const fieldNames={vendor:'Supplier',invoiceNumber:'Invoice number',date:'Invoice date',po:'PO reference',currency:'Currency',subtotal:'Subtotal',tax:'Tax',total:'Total'};
function fieldsHtml(r){return `<div class="fields-grid">${Object.entries(fieldNames).map(([k,label])=>{const src=r.fields.sources[k],missing=r.fields[k]===null||r.fields[k]==='';return `<div class="field${missing?' missing':''}"${src&&!src.reviewed?` data-line="${src.lineNumber}"`:''}><label>${label}</label><strong>${missing?'Not found':esc(['subtotal','tax','total'].includes(k)?money(r.fields[k],r.fields.currency||'USD'):r.fields[k])}</strong><small>${src?(src.reviewed?`<span class="initials">${esc(initials(src.line.replace(/^Verified by /,'')))}</span>${esc(src.line)}`:`${tickmark()}Line ${src.lineNumber}`):'No source line'}</small></div>`;}).join('')}</div>`;}
function sheetLines(r){return String(r.rawText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);}
// The extracted text as a printed sheet. Line numbers match the engine's lineNumber, so each traced field lands on its own line.
function sourceSheet(r){const lines=sheetLines(r),traced={},isPage=l=>/^--- Page \d+ ---$/.test(l);for(const [k,s] of Object.entries(r.fields.sources||{}))if(s&&!s.reviewed)(traced[s.lineNumber]??=[]).push(fieldNames[k]||k);for(const item of r.fields.items||[])(traced[item.lineNumber]??=[]).push('Item');const body=lines.map((l,i)=>{const n=i+1,marks=traced[n];if(isPage(l))return `<div class="sheet-page">${esc(l.replace(/-/g,'').trim())}</div>`;return `<div class="sheet-line${marks?' traced':''}" data-line="${n}"><span class="ln">${n}</span><span class="txt">${esc(l)}</span>${marks?`<span class="mark">${tickmark()}<span>${esc(marks.join(', '))}</span></span>`:''}</div>`;}).join('');return `<figure class="sheet-wrap"><figcaption><span>Extracted text</span><span>${plural(r.pages,'page')}</span></figcaption><div class="sheet">${lines.every(isPage)?'<div class="sheet-empty">No searchable text in this PDF. OCR is not configured, so verify each field against the original.</div>':body}</div><div class="sheet-foot"><span>SHA-256</span><code>${esc(r.hash)}</code><p>A local fingerprint of the uploaded file, not an authentication record. The JSON export keeps the original extraction and every correction.</p></div></figure>`;}
function budgetEvidence(r){const po=r.registerSnapshot?.find(p=>p.id===r.matchedPo);if(!po||!Number.isSafeInteger(r.fields.total))return '';const prior=(r.priorApproved||[]).filter(p=>p.matchedPo===po.id).reduce((sum,p)=>sum+p.total,0),used=po.committed+prior,available=po.total-used,tolerance=Math.min(Math.round(po.total*0.02),2500),limit=po.total+tolerance,request=r.status==='Blocked'?0:r.fields.total,within=Math.max(0,Math.min(request,limit-used)),over=Math.max(0,used+request-limit),scale=Math.max(limit,used+request),pct=n=>n/scale*100,mode=r.status==='Approved'?'reserved':r.status==='Blocked'?'unchanged':'held';return `<div class="section-label"><span>PO budget</span><span>${r.status==='Approved'?'Reserved':r.status==='Blocked'?'No new commitment':'Held for review'}</span></div><section class="budget-evidence ${mode}"><div class="budget-head"><h3>${esc(po.id)} <span>${esc(po.description)}</span></h3><span class="budget-total">Authorized ${money(po.total,po.currency)}</span></div><div class="commitment-bar" role="img" aria-label="${esc(money(used,po.currency))} already committed; ${esc(money(request,po.currency))} ${r.status==='Approved'?'new reservation':'uncommitted request'}${over?`; ${esc(money(over,po.currency))} beyond the PO and tolerance`:''}"><span class="commitment-used" style="width:${pct(used)}%"></span><span class="commitment-request" style="width:${pct(within)}%"></span><span class="commitment-over" style="width:${pct(over)}%"></span><span class="commitment-limit" style="left:${pct(po.total)}%"></span><span class="commitment-tolerance" style="left:${pct(po.total)}%;width:${pct(tolerance)}%"></span></div><div class="budget-ledger"><div><span><i class="swatch used"></i>Earlier commitments</span><strong>${money(used,po.currency)}</strong></div><div><span><i class="swatch open"></i>Available before invoice</span><strong>${money(available,po.currency)}</strong></div><div class="ledger-request"><span><i class="swatch request"></i>This invoice</span><strong>${money(r.fields.total,po.currency)}</strong></div>${over?`<div class="ledger-over"><span><i class="swatch over"></i>Beyond PO and tolerance</span><strong>${money(over,po.currency)}</strong></div>`:''}</div><div class="budget-foot"><span>${r.status==='Approved'?`Remaining after reservation: ${money(available-r.fields.total,po.currency)}`:r.status==='Blocked'?`Budget unchanged: ${money(available,po.currency)}`:'Held for review, so no budget is reserved'}</span><span>Tolerance ${money(tolerance,po.currency)}</span></div></section>`;}
function showRun(id){const r=state.runs.find(r=>r.id===id);if(!r)return;activeRun=id;const controls=r.checks.map((c,i)=>({...c,ref:String(i+1).padStart(2,'0')})).sort((a,b)=>(a.result==='pass')-(b.result==='pass'));drawer(`Invoice ${r.fields.invoiceNumber||'needs identification'}`,`${id} · ${when(r.createdAt)} · ${seconds(r.durationMs)}`,`<div class="review-layout"><div class="decision-col">${stages(5)}<div class="file-strip">${icon('FileText')}<div><strong>${esc(r.filename)}</strong><small>${plural(r.pages,'page')} · ${(r.filesize/1024).toFixed(1)} KB · ${r.source}</small></div><button class="btn small" data-action="original">${icon('FileText')} Open original</button></div><div class="result-hero ${statusClass(r.status)}"><div class="result-top"><h3>${esc(r.status==='Approved'?'Ready for AP':r.status==='Blocked'?'Blocked by a control':'Verification required')}</h3>${badge(r.status)}</div><p>${esc(r.nextAction)}</p><div class="result-actions"><button class="btn small" data-action="export-run">${icon('Download')} Decision JSON</button>${r.status==='Needs review'?'<button class="btn small primary" data-action="review">Verify & recheck fields</button>':''}</div></div><div id="review-area"></div>${budgetEvidence(r)}<div class="section-label"><span>Extracted evidence</span><span>${r.fields.currency||'—'} · ${r.matchedPo||'Unmatched PO'}</span></div>${fieldsHtml(r)}<div class="section-label"><span>Decision controls</span><span>${r.checks.filter(c=>c.result==='pass').length} / ${r.checks.length} passed</span></div><div class="checks">${controls.map(c=>`<div class="check ${c.result}" id="control-${esc(c.code)}"><span class="control-reference">${c.ref}</span><span class="check-symbol ${c.result}">${c.result==='pass'?tickmark():icon(c.result==='block'?'X':'CircleAlert')}</span><div><b>${esc(c.label)}</b><p>${esc(c.detail)}</p></div></div>`).join('')}</div>${r.corrections.length?`<div class="section-label"><span>Human review audit</span></div>${r.corrections.map(c=>`<div class="audit-note"><span class="initials">${esc(initials(c.reviewer))}</span><div><strong>${esc(c.reviewer)}</strong> · ${when(c.at)}<br>${esc(c.note)}<br>${Object.entries(c.changes).map(([k,v])=>`${esc(fieldNames[k]||k)}: ${esc(v.before??'missing')} → ${esc(v.after??'missing')}`).join(' · ')||'Fields confirmed without changes'}<br>Previous decision: ${esc(c.previousDecision.status)}</div></div>`).join('')}`:''}<details><summary>${icon('ChevronRight')}Processing audit</summary><div class="evidence">${r.logs.map(l=>`${l.at} · ${l.detail}`).map(esc).join('\n')}\nPolicy: ${r.policyVersion}\nDecision made in ${r.durationMs} ms</div></details></div><aside class="sheet-col" aria-label="Source document"><div id="source-preview" class="hidden"></div>${sourceSheet(r)}</aside></div>`,true);activeRun=id;}
function reviewForm(){const r=state.runs.find(r=>r.id===activeRun);if(!r||r.status!=='Needs review')return;$('#review-area').innerHTML=`<form class="review-form" id="review-form"><h3>Verify against the original PDF</h3><p>Open the original, confirm the evidence, and identify yourself. Corrections create an audit entry; all controls run again. This does not bypass budget, duplicate or extracted item-arithmetic rules. If extracted item rows are wrong, obtain a corrected PDF. A PO selection must be independently confirmed with procurement.</p><div class="form-grid">${Object.entries(fieldNames).map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(['subtotal','tax','total'].includes(k)?(r.fields[k]===null?'':(r.fields[k]/100).toFixed(2)):r.fields[k]||'')}" required ${k==='date'?'type="date"':k==='currency'?'pattern="[A-Z]{3}" maxlength="3"':''} ${['subtotal','tax','total'].includes(k)?'inputmode="decimal"':''} maxlength="200"></label>`).join('')}<label>Reviewer name<input name="reviewer" required minlength="2" maxlength="100" placeholder="Your name"></label><label class="wide">Verification note<textarea name="note" required minlength="12" maxlength="1000" placeholder="What did you verify, and where did the PO confirmation come from?"></textarea></label></div><p><label><input type="checkbox" required> I checked these values against the source and verified the intended PO.</label></p><button class="btn primary" type="submit">Save verification & recheck</button></form>`;$('#review-form').addEventListener('submit',submitReview);$('#review-area').scrollIntoView({behavior:'smooth',block:'start'});}
async function submitReview(e){e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));try{const id=activeRun;await lock(async()=>{const s=read(),r=s.runs.find(r=>r.id===id);if(!r||r.status!=='Needs review')throw new Error('This run has already changed. Reopen its latest decision.');const before=structuredClone(r.fields),fields=correctInvoiceFields(before,data,data.reviewer.trim()),changes={};for(const k of Object.keys(fieldNames))if(before[k]!==fields[k])changes[k]={before:before[k],after:fields[k]};const decision=evaluate(fields,s,{hash:r.hash,excludeId:id});r.corrections.push({at:new Date().toISOString(),reviewer:data.reviewer.trim(),note:data.note.trim(),changes,previousFields:before,previousDecision:{status:r.status,checks:structuredClone(r.checks)}});Object.assign(r,{fields,...decision,reviewedAt:new Date().toISOString(),registerSnapshot:structuredClone(s.pos),priorApproved:s.runs.filter(x=>x.id!==id&&x.status==='Approved').map(x=>({id:x.id,matchedPo:x.matchedPo,total:x.fields.total,currency:x.fields.currency}))});save(s);});render();showRun(id);toast('Verification saved and every control rechecked');}catch(e){toast(e.message);}}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportAll(){download(JSON.stringify({exportedAt:new Date().toISOString(),policyVersion:POLICY_VERSION,...state},null,2),'ledgerline-audit.json');}
function exportPos(){const header='id,vendorId,description,currency,total,committed,status';download(header+'\n'+state.pos.map(p=>[p.id,p.vendorId,p.description.replaceAll(',',' '),p.currency,(p.total/100).toFixed(2),(p.committed/100).toFixed(2),p.status].join(',')).join('\n')+'\n','purchase-orders.csv','text/csv');}
async function renderSource(){const area=$('#source-preview');if(!previewDoc||!area)return;const pg=await previewDoc.getPage(previewPage),vp=pg.getViewport({scale:1.2});area.innerHTML=`<div class="source-toolbar"><strong>Original PDF · page ${previewPage} / ${previewDoc.numPages}</strong><div><button class="btn small" data-action="source-prev" aria-label="Previous PDF page" ${previewPage===1?'disabled':''}>${icon('ChevronRight')}</button> <button class="btn small" data-action="source-next" aria-label="Next PDF page" ${previewPage===previewDoc.numPages?'disabled':''}>${icon('ChevronRight')}</button> <button class="btn small" data-action="source-close">Hide source</button></div></div><div class="source-scroll"><canvas id="source-canvas" aria-label="Original invoice PDF page ${previewPage}"></canvas></div>`;area.classList.remove('hidden');const canvas=$('#source-canvas');canvas.width=vp.width;canvas.height=vp.height;await pg.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;}
async function original(){const r=state.runs.find(r=>r.id===activeRun);if(!r)return;try{if(!previewDoc){const file=await fileGet(r.id);if(!file)throw new Error('Original file is not available in this browser. Upload it again for verification.');previewDoc=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;previewPage=1;}await renderSource();$('#source-preview').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message);}}
async function reset(){if(running)return;drawer('Reset this demo workspace?','This clears local runs, PDFs and PO changes',`<div class="notice">Save your audit export first. This only affects this browser workspace; no external records are changed.</div><div class="result-actions"><button class="btn" data-action="export-all">Export before resetting</button><button class="btn primary" data-action="confirm-reset">Reset workspace</button><button class="btn" data-action="close">Cancel</button></div>`);}
async function confirmReset(){try{await lock(async()=>{const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=reject;});storageError='';save(emptyState());});closeDrawer();go('overview');toast('Workspace reset for a fresh demo');}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-run],[data-go]');if(!b)return;if(b.dataset.view)return go(b.dataset.view);if(b.dataset.go)return go(b.dataset.go);if(b.dataset.sample!==undefined)return sample(Number(b.dataset.sample));if(b.dataset.run)return showRun(b.dataset.run);const a=b.dataset.action;try{if(a==='menu')nav(!document.body.classList.contains('nav-open'));if(a==='new')openNew();if(a==='upload')chooseFile();if(a==='close')closeDrawer();if(a==='review')reviewForm();if(a==='original')await original();if(a==='source-next'&&previewDoc){previewPage=Math.min(previewDoc.numPages,previewPage+1);await renderSource();}if(a==='source-prev'&&previewDoc){previewPage=Math.max(1,previewPage-1);await renderSource();}if(a==='source-close')$('#source-preview').classList.add('hidden');if(a==='export-all')exportAll();if(a==='export-pos')exportPos();if(a==='export-run'){const r=state.runs.find(r=>r.id===activeRun);download(JSON.stringify(r,null,2),`${r.id}-decision.json`);}if(a==='reset')reset();if(a==='confirm-reset')await confirmReset();if(a==='import-pos'){if(state.runs.length)return toast('Export and reset before replacing the PO register.');$('#csv-file').click();}}catch(e){toast(e.message);}});
$('#csv-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw new Error('PO CSV must be smaller than 100 KB.');const csv=await file.text();await lock(async()=>{const s=read();if(s.runs.length)throw new Error('Workspace now has runs. Reset before replacing POs.');s.pos=parsePoCsv(csv,s);save(s);});render();toast(`Imported ${plural(state.pos.length,'purchase order')}`);}catch(e){toast(e.message);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('nav-open'))return nav(false);closeDrawer();}if(e.key==='Enter'&&e.target.matches('[data-run]'))showRun(e.target.dataset.run);if(e.key==='Tab'&&$('.drawer')){const focusables=[...$('.drawer').querySelectorAll('button:not(:disabled),a,input,textarea,select,summary,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
document.addEventListener('mouseover',e=>{const f=e.target.closest('.field[data-line]'),lit=document.querySelector('.sheet-line.lit');if(lit&&lit.dataset.line===f?.dataset.line)return;lit?.classList.remove('lit');if(f)document.querySelector(`.sheet-line[data-line="${f.dataset.line}"]`)?.classList.add('lit');});
window.addEventListener('storage',e=>{if(e.key===KEY&&!running){state=read();render();if(activeRun&&state.runs.some(r=>r.id===activeRun))showRun(activeRun);else closeDrawer();}});
render();
